                    if (country == "IL") {
                    InfoCard(tr(R.string.text_69e69a7518)) {
                        NumberField(tr(R.string.text_70d7cd14f1), values.getValue("points"), !busy) { set("points", it) }
                        Text(tr(R.string.text_9987c69efd), style = MaterialTheme.typography.bodySmall)
                    }
                    InfoCard(tr(R.string.text_8cee38323a)) {
                        NumberField(tr(R.string.text_9982697de0), values.getValue("pension"), !busy) { set("pension", it) }
                        NumberField(tr(R.string.text_3638d5596d), values.getValue("study"), !busy) { set("study", it) }
                        Text(tr(R.string.text_90b68945c0), style = MaterialTheme.typography.bodySmall)
                        Text(tr(R.string.text_e2e16aa700))
                        listOf("BASE" to tr(R.string.text_dc959b16aa), "GROSS" to tr(R.string.text_682c0e2622), "CUSTOM" to tr(R.string.text_3f55564e26)).forEach { (key, label) ->
                            Row(verticalAlignment = Alignment.CenterVertically) { RadioButton(basis == key, onClick = { basis = key }, enabled = !busy); Text(label, modifier = Modifier.weight(1f)) }
                        }
                        if (basis == "CUSTOM") NumberField(tr(R.string.text_0d4b9a288d), values.getValue("custom"), !busy) { set("custom", it) }
                        SettingSwitch(tr(R.string.text_3284189b89), pensionCredit, !busy) { pensionCredit = it }
                        Text(tr(R.string.text_0b5e7d7238), style = MaterialTheme.typography.bodySmall)
                    }
                    InfoCard(tr(R.string.text_102196cdf2)) {
                        Text(tr(R.string.text_c02d9dbae9))
                        Text(tr(R.string.text_a09a8853d1), style = MaterialTheme.typography.bodySmall)
                    }
                    } else Text(tr(R.string.tax_foreign_fields))
                
                }
                3 -> {
                    InfoCard(tr(R.string.language_title)) { LanguageSelector() }
                    ThemeSelector(appearance,!busy) { appearance=it;error=null }
                }
            }
        }
    }
}

internal fun normalizedNumber(text: String): String = buildString {
    text.forEach { c ->
        val digit = Character.digit(c, 10)
        when {
            digit >= 0 -> append(('0'.code + digit).toChar())
            c == '\u066b' || c == '\uff0e' -> append('.')
            c == '\uff1a' -> append(':')
            c == '\u066c' -> Unit
            else -> append(c)
        }
    }
}
internal fun String.asLocalizedInt(): Int? = normalizedNumber(this).toIntOrNull()
